-- Import bundled exports into the same database used by Home / Local.
local function seed_offline_presets(database)
    local storage_key = "emberlashkoxoxoxofam"
    local imported_key = "emberlash.offline_presets.imported.v1"
    local configs = database.read(storage_key)
    local imported = database.read(imported_key)
        if configs == nil then configs = {} end
        if imported == nil then imported = {} end
    assert(type(configs) == "table", "emberlash: invalid Local preset database")
    assert(type(imported) == "table", "emberlash: invalid bundled preset import journal")
    
    local names, codes = {}, {}
    for _, config in ipairs(configs) do
        if type(config) == "table" then
                if type(config.name) == "string" then names[config.name] = true end
                if type(config.code) == "string" then codes[config.code] = true end
        end
    end
    
    local added, changed = 0, false
    for _, preset in ipairs(offline_preset_exports) do
        if not imported[preset.id] then
            if not names[preset.name] and not codes[preset.code] then
                configs[#configs + 1] = {name = preset.name, code = preset.code}
                names[preset.name], codes[preset.code] = true, true
                added = added + 1
            end
            imported[preset.id] = true
            changed = true
        end
    end
    if changed then
            if added > 0 then database.write(storage_key, configs) end
        database.write(imported_key, imported)
        database.flush()
    end
    return added
end
end

